class OrderedStream {
    private String[] data;
    private int ptr;
    public OrderedStream(int n) {
        data = new String[n + 1];
        ptr = 1;
    }
    public List<String> insert(int idKey, String value) {
        data[idKey] = value;
        List<String> res = new java.util.ArrayList<>();
        while (ptr < data.length && data[ptr] != null) {
            res.add(data[ptr]);
            ptr++;
        }
        return res;
    }
}

import java.util.*;

class OrderedStream {
    private Map<Integer, String> map;
    private int ptr;
    public OrderedStream(int n) {
        map = new HashMap();
        ptr = 1;
    }
    public List<String> insert(int idKey, String value) {
        map.put(idKey, value);
        List<String> res = new ArrayList();
        while (map.containsKey(ptr)) {
            res.add(map.get(ptr));
            ptr++;
        }
        return res;
    }
}
